//! Contextual chunking (Feature 4).
//!
//! Wraps an existing chunker and enriches each chunk with a context sentence
//! generated by the LLM. The context sentence is prepended to the chunk content
//! before embedding, improving retrieval quality for ambiguous chunks.

use async_trait::async_trait;
use easyrag_core::llm::service::{LlmRequest, LlmService};
use easyrag_core::prompt::{format_prompt, CONTEXTUAL_CHUNKING_PROMPT};
use easyrag_core::JsonValue;
use std::collections::HashMap;
use std::sync::Arc;

use crate::chunker::{Chunker, TextChunk};

/// A chunker wrapper that enriches each chunk with a context sentence.
///
/// The context sentence is generated by the LLM based on the full document
/// and the chunk content. It is prepended to the chunk content to improve
/// retrieval quality.
pub struct ContextualChunker {
    llm_service: Arc<dyn LlmService>,
    inner: Arc<dyn Chunker>,
    /// Maximum number of concurrent LLM calls for context generation.
    max_concurrent: usize,
}

impl ContextualChunker {
    pub fn new(llm_service: Arc<dyn LlmService>, inner: Arc<dyn Chunker>) -> Self {
        Self {
            llm_service,
            inner,
            max_concurrent: 8,
        }
    }

    pub fn with_max_concurrent(mut self, max: usize) -> Self {
        // 0 would create a Semaphore with no permits, hanging every
        // enrichment task forever.
        self.max_concurrent = max.max(1);
        self
    }

    /// Enrich chunks with context sentences.
    async fn enrich_with_context(
        &self,
        chunks: Vec<TextChunk>,
        full_doc_content: &str,
    ) -> easyrag_core::Result<Vec<TextChunk>> {
        if chunks.is_empty() {
            return Ok(chunks);
        }

        // Truncate document preview to avoid excessive token usage
        let doc_preview = full_doc_content.chars().take(4000).collect::<String>();

        // Process chunks with bounded concurrency
        let semaphore = Arc::new(tokio::sync::Semaphore::new(self.max_concurrent));
        let mut handles = Vec::with_capacity(chunks.len());

        for chunk in chunks {
            let llm = Arc::clone(&self.llm_service);
            let permit = Arc::clone(&semaphore);
            let preview = doc_preview.clone();
            let chunk_content = chunk.content.clone();

            let handle = tokio::spawn(async move {
                let _permit = permit.acquire().await;
                Self::generate_context_sentence(&llm, &preview, &chunk_content).await
            });
            handles.push((chunk, handle));
        }

        // Collect results
        let mut enriched_chunks = Vec::with_capacity(handles.len());
        for (mut chunk, handle) in handles {
            match handle.await {
                Ok(Ok(Some(context_sentence))) => {
                    // Store original content in metadata
                    let mut metadata = chunk.metadata.clone();
                    metadata.insert(
                        "original_content".to_string(),
                        JsonValue::String(chunk.content.clone()),
                    );
                    metadata.insert(
                        "context_sentence".to_string(),
                        JsonValue::String(context_sentence.clone()),
                    );
                    chunk.metadata = metadata;

                    // Prepend context sentence to chunk content
                    chunk.content = format!("{context_sentence}\n\n{}", chunk.content);
                }
                Ok(Ok(None)) => {
                    // No context generated — keep chunk as-is
                }
                Ok(Err(e)) => {
                    tracing::warn!("Context generation failed for chunk: {e}");
                }
                Err(e) => {
                    tracing::warn!("Context generation task failed: {e}");
                }
            }
            enriched_chunks.push(chunk);
        }

        Ok(enriched_chunks)
    }

    /// Generate a context sentence for a single chunk.
    async fn generate_context_sentence(
        llm_service: &Arc<dyn LlmService>,
        doc_preview: &str,
        chunk_content: &str,
    ) -> easyrag_core::Result<Option<String>> {
        let mut vars = HashMap::new();
        vars.insert("doc_preview".to_string(), doc_preview.to_string());
        vars.insert("chunk_content".to_string(), chunk_content.to_string());
        let prompt = format_prompt(CONTEXTUAL_CHUNKING_PROMPT, &vars);

        let request = LlmRequest::new(&prompt).with_max_tokens(64);
        let response = llm_service.complete(&request).await?;

        let sentence = response.trim().to_string();
        if sentence.is_empty() || sentence.len() < 10 {
            return Ok(None);
        }

        Ok(Some(sentence))
    }
}

#[async_trait]
impl Chunker for ContextualChunker {
    async fn chunk(&self, text: &str, doc_id: &str) -> easyrag_core::Result<Vec<TextChunk>> {
        // First, chunk using the inner chunker
        let chunks = self.inner.chunk(text, doc_id).await?;

        // Then enrich with context
        self.enrich_with_context(chunks, text).await
    }

    fn chunker_type(&self) -> &'static str {
        "contextual"
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn contextual_chunker_type() {
        struct DummyChunker;
        #[async_trait]
        impl Chunker for DummyChunker {
            async fn chunk(&self, _text: &str, _doc_id: &str) -> easyrag_core::Result<Vec<TextChunk>> {
                Ok(Vec::new())
            }
            fn chunker_type(&self) -> &'static str { "dummy" }
        }

        struct DummyLlm;
        #[async_trait]
        impl LlmService for DummyLlm {
            async fn complete(&self, _request: &LlmRequest) -> easyrag_core::Result<String> {
                Ok("This chunk discusses the introduction.".to_string())
            }
            fn complete_stream(&self, _request: LlmRequest) -> futures::stream::BoxStream<'static, String> {
                unimplemented!()
            }
        }

        let chunker = ContextualChunker::new(Arc::new(DummyLlm), Arc::new(DummyChunker));
        assert_eq!(chunker.chunker_type(), "contextual");
    }
}
